<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Amazon Product Catalog Performance & Customer Sentiment Analysis</title>
    <style>
        :root {
            --primary: #1a73e8;
            --secondary: #5f6368;
            --accent: #34a853;
            --warning: #ea4335;
            --gold: #fbbc04;
            --dark: #202124;
            --light-bg: #f8f9fa;
            --border: #e0e0e0;
        }
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: 'Segoe UI', Arial, sans-serif; color: var(--dark); background: #fff; line-height: 1.6; }
        .container { max-width: 1200px; margin: 0 auto; padding: 20px; }
        header { background: linear-gradient(135deg, var(--primary), #0d47a1); color: white; padding: 40px 0; margin-bottom: 40px; }
        header h1 { font-size: 28px; font-weight: 600; margin-bottom: 8px; }
        header .subtitle { opacity: 0.9; font-size: 16px; }
        h2 { color: var(--dark); font-size: 22px; margin-bottom: 20px; padding-bottom: 10px; border-bottom: 3px solid var(--primary); }
        h3 { color: var(--secondary); font-size: 16px; margin: 20px 0 12px; }
        .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 20px; margin: 30px 0; }
        .kpi-card { background: var(--light-bg); border-radius: 12px; padding: 24px; text-align: center; border: 1px solid var(--border); }
        .kpi-card .value { font-size: 36px; font-weight: 700; color: var(--primary); }
        .kpi-card .label { color: var(--secondary); font-size: 14px; margin-top: 8px; }
        .kpi-card.highlight { background: linear-gradient(135deg, #e8f0fe, #d2e3fc); border-color: var(--primary); }
        .kpi-card.positive .value { color: var(--accent); }
        .kpi-card.warning .value { color: var(--warning); }
        .chart-container { margin: 30px 0; text-align: center; }
        .chart-container img { max-width: 100%; height: auto; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
        .section { margin-bottom: 50px; }
        .insight-box { background: #e8f5e9; border-left: 4px solid var(--accent); padding: 16px 20px; margin: 20px 0; border-radius: 0 8px 8px 0; }
        .insight-box.warning { background: #fce8e6; border-left-color: var(--warning); }
        .insight-box.info { background: #e8f0fe; border-left-color: var(--primary); }
        table { width: 100%; border-collapse: collapse; margin: 20px 0; }
        th { background: var(--primary); color: white; padding: 12px 16px; text-align: left; font-weight: 600; }
        td { padding: 12px 16px; border-bottom: 1px solid var(--border); }
        tr:hover { background: var(--light-bg); }
        .correlation-matrix { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; margin: 20px 0; }
        .corr-item { background: var(--light-bg); padding: 20px; border-radius: 8px; text-align: center; }
        .corr-item .corr-value { font-size: 28px; font-weight: 700; }
        .corr-item .corr-label { font-size: 13px; color: var(--secondary); margin-top: 4px; }
        .recommendation { background: white; border: 1px solid var(--border); border-radius: 12px; padding: 24px; margin: 16px 0; box-shadow: 0 2px 6px rgba(0,0,0,0.05); }
        .recommendation h4 { color: var(--primary); font-size: 18px; margin-bottom: 12px; }
        .recommendation p { color: var(--secondary); line-height: 1.7; }

